with keys(idempotency_key) as (values
 ('00000000-0000-4000-8000-000000000101'::uuid),('00000000-0000-4000-8000-000000000102'::uuid),('00000000-0000-4000-8000-000000000103'::uuid),('00000000-0000-4000-8000-000000000104'::uuid),('00000000-0000-4000-8000-000000000105'::uuid),('00000000-0000-4000-8000-000000000106'::uuid),('00000000-0000-4000-8000-000000000107'::uuid),('00000000-0000-4000-8000-000000000108'::uuid),('00000000-0000-4000-8000-000000000109'::uuid),('00000000-0000-4000-8000-000000000110'::uuid),('00000000-0000-4000-8000-000000000111'::uuid),('00000000-0000-4000-8000-000000000112'::uuid),('00000000-0000-4000-8000-000000000113'::uuid)),
events as (select id from public.financial_events where description like 'TEST_FE_20260809%' and idempotency_key in(select idempotency_key from keys)),
ambiguous as (select exists(select 1 from public.financial_events where description like 'TEST_FE_20260809%' and idempotency_key not in(select idempotency_key from keys)) unexpected_tag,exists(select 1 from public.financial_events where description not like 'TEST_FE_20260809%' and idempotency_key in(select idempotency_key from keys)) conflicting_key)
